contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 burnAmount) public {
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 otherSupply = beforeSupply - beforeBalance;
        require(burnAmount <= beforeBalance);

        bool reverted = false;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterBalance == beforeBalance - burnAmount && afterSupply == beforeSupply - burnAmount && afterSupply == afterBalance + otherSupply);
    }
}

